@inject RecipeShare.Services.RecipeService RecipeService

<div class="my-3">
    <strong>Rate this recipe:</strong>
    <span class="ms-2">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span role="button" style="cursor:pointer; font-size:1.5rem;" @onclick="() => Rate(star)">
                @(star <= SelectedRating ? "★" : "☆")
            </span>
        }
    </span>

    @if (Submitted)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }

    @if (Recipe is not null && Recipe.RatingCount > 0)
    {
        <span class="ms-3 text-muted">Average: @Recipe.AverageRating.ToString("F1") ⭐ (@Recipe.RatingCount ratings)</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int SelectedRating { get; set; }
    private bool Submitted { get; set; }
    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(RecipeId);
    }

    private void Rate(int stars)
    {
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        Recipe = RecipeService.GetRecipeById(RecipeId);
        Submitted = true;
    }
}

